def solve(tokens):
    import operator
    ops = {'+': operator.add, '-': operator.sub, '*': operator.mul}
    stack = []
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[tok](a, b))
        elif tok == '/':
            b = stack.pop()
            a = stack.pop()
            q = abs(a) // abs(b)
            stack.append(q if (a >= 0) == (b >= 0) else -q)
        else:
            stack.append(int(tok))
    return stack[0]

