def solve(grid):
    # Handle empty grid or grid with empty rows
    if not grid:
        return 0
    n = len(grid)
    visited = []
    for row in grid:
        visited.append([False]*len(row))
    def dfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if x < 0 or x >= n:
                continue
            if y < 0 or y >= len(grid[x]):
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    count = 0
    for i in range(n):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i,j)
                count += 1
    return count

